def bs(i,j,key):
	global final
	if key>final[j]:
		return j
	if key<final[i]:
		return -1
	while j-i>1:
		mid=(i+j)/2
		if final[mid]<key:
			i=mid
		elif final[mid]>=key:
			j=mid-1
	if final[j]<key:
		return j
	elif final[i]<key:
		return i
